          <path d="M20 90 Q50 30 80 90" fill="#AED6F1" stroke="black" strokeWidth="2" />
          <circle cx="50" cy="40" r="25" fill="#f1c27d" stroke="black" strokeWidth="2" />
          <path d="M25 40 Q50 10 75 40" fill="#2E86C1" stroke="black" strokeWidth="1" />
          <rect x="35" y="35" width="8" height="3" fill="black" />
          <rect x="57" y="35" width="8" height="3" fill="black" />
