    case 'Toxic Tommy':
      return (
        <svg viewBox="0 0 100 100" className="w-full h-full">
          <rect width="100" height="100" fill="#091A0D" />
          <rect x="25" y="30" width="50" height="50" fill="#27AE60" stroke="black" strokeWidth="2" />
          <circle cx="40" cy="50" r="8" fill="#111" />
          <circle cx="60" cy="50" r="8" fill="#111" />
        </svg>
      );
    case 'Blackout Barry':
      return (
        <svg viewBox="0 0 100 100" className="w-full h-full">
          <rect width="100" height="100" fill="#000" />
          <path d="M30 20 L70 20 L80 90 L20 90 Z" fill="#2C3E50" stroke="#3498DB" strokeWidth="2" />
