    'BOULDER': MAX_AMMO['BOULDER'],
    'SHOTGUN': MAX_AMMO['SHOTGUN'],
    'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
    'TSUNAMI': MAX_AMMO['TSUNAMI'],
    'NEEDLES': MAX_AMMO['NEEDLES'],
