        for(let j=0; j<4; j++){ ctx.beginPath(); const sx = e.width/2, sy = e.height/2; ctx.moveTo(sx, sy); ctx.lineTo(sx + (Math.random()-0.5)*100, sy + (Math.random()-0.5)*100); ctx.stroke(); }
      }
      if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); } 
      if (e.needleCount && e.needleOffsets) { ctx.filter = 'none'; e.needleOffsets.forEach(off => { ctx.save(); ctx.translate(e.pos.x + off.x, e.pos.y + off.y); ctx.rotate(off.rot); ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(0, -1, 14, 2); ctx.fillStyle = 'red'; ctx.fillRect(14, -2, 5, 4); ctx.restore(); }); }
