    if (status !== GameStatus.LEVEL_INTRO || state.introTimer >= 80) { drawPlayer(ctx, player); if (state.playerLastVulgarity && state.playerVulgarityTimer > 0 && state.bossExplosionTimer <= 0) { ctx.save(); ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center'; ctx.fillText(state.playerLastVulgarity, player.pos.x + player.width / 2, player.pos.y - 20); ctx.restore(); } }
    state.projectiles.forEach(p => { 
      ctx.save();
      if (p.isTased) ctx.translate((Math.random()-0.5)*10, (Math.random()-0.5)*10);
      if (p.isBoulder) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = p.owner === 'player' ? '#8B4513' : '#4E342E'; ctx.beginPath(); const seg = 10, bR = p.width / 2; for (let i = 0; i < seg; i++) { const a = (i / seg) * Math.PI * 2, v = 0.85 + Math.abs(Math.sin(i * 3 + (p.id.length % 5))) * 0.3, r = bR * v, x = Math.cos(a) * r, y = Math.sin(a) * r; if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); } ctx.closePath(); ctx.fill(); ctx.strokeStyle = 'rgba(0,0,0,0.4)'; ctx.lineWidth = 1.5; for (let j = 0; j < 3; j++) { const ra = (j * 2.1) + (p.id.length % 10); ctx.beginPath(); ctx.moveTo(Math.cos(ra) * bR * 0.2, Math.sin(ra) * bR * 0.2); ctx.lineTo(Math.cos(ra) * bR * 0.7, Math.sin(ra) * bR * 0.7); ctx.stroke(); } ctx.strokeStyle = 'black'; ctx.lineWidth = 2; ctx.stroke(); ctx.restore(); } 
      else if (p.isCocaine) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(state.frame * 0.1); ctx.fillStyle = '#fff'; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeStyle = '#ccc'; ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); ctx.restore(); } 
      else if (p.isMethBarrel) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.rotation || 0); ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); ctx.fillStyle = '#FFD700'; ctx.font = 'bold 8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", 0, 5); if (p.health > 0) { ctx.fillStyle = '#00FF00'; ctx.fillRect(-p.width/2, -p.height/2 - 8, (p.health / 100) * p.width, 4); } ctx.restore(); } 
